CREATE TABLE managed_servers (id BIGSERIAL PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, name VARCHAR(100) NOT NULL, host VARCHAR(255) NOT NULL, environment VARCHAR(64) NOT NULL, labels TEXT NOT NULL DEFAULT '{}', status VARCHAR(16) NOT NULL, agent_token_hash VARCHAR(64), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_seen TIMESTAMPTZ);
CREATE TABLE enrollment_tokens (id BIGSERIAL PRIMARY KEY, server_id BIGINT NOT NULL REFERENCES managed_servers(id) ON DELETE CASCADE, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, used_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE server_heartbeats (id BIGSERIAL PRIMARY KEY, server_id BIGINT NOT NULL REFERENCES managed_servers(id) ON DELETE CASCADE, cpu_percent INTEGER NOT NULL, ram_percent INTEGER NOT NULL, disk_percent INTEGER NOT NULL, managed_containers INTEGER NOT NULL, docker_version VARCHAR(100), os VARCHAR(100), agent_version VARCHAR(100), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
